import React, { useRef, useState, useMemo, useEffect, useCallback, useLayoutEffect } from 'react';
import { Canvas, useThree, ThreeEvent, useFrame } from '@react-three/fiber';
import { OrbitControls, Grid, TransformControls, Html, GizmoHelper, GizmoViewport, Text, Billboard } from '@react-three/drei';
import * as THREE from 'three';
import { useApp } from '../context/AppContext';
import { ToolType, IPoint, IShape, IGuideLine } from '../types';
import { SNAP_GRID, DEFAULT_COLOR, FLAT_COLOR, HIGHLIGHT_COLOR, DEFAULT_HEIGHT } from '../constants';

// --- Constants ---
const SNAP_THRESHOLD = 0.3; // Ray distance threshold
const ALIGN_THRESHOLD = 0.4; // Axis alignment threshold
const SNAP_CULLING_DISTANCE = 15; // Distance to ignore geometry snapping
const EPSILON = 1e-4;

// --- Helper: Get Local Basis Vectors from Normal ---
const getLocalBasis = (normal: THREE.Vector3) => {
    const n = normal.clone().normalize();
    let up = new THREE.Vector3(0, 1, 0);
    if (Math.abs(n.dot(up)) > 0.99) up.set(0, 0, 1);

    const right = new THREE.Vector3().crossVectors(n, up).normalize();
    const top = new THREE.Vector3().crossVectors(right, n).normalize(); 

    return { right, top, normal: n };
};

const getDimensionRotation = (p1: THREE.Vector3, p2: THREE.Vector3, offsetVector: THREE.Vector3) => {
    const direction = new THREE.Vector3().subVectors(p2, p1).normalize();
    if (direction.lengthSq() < 0.0001) return new THREE.Quaternion();

    let up = offsetVector.clone().normalize();

    // Handle zero/small offset (fallback to world up or orthogonal)
    if (offsetVector.lengthSq() < 0.0001) {
         const worldUp = new THREE.Vector3(0, 1, 0);
         // If line is nearly vertical, use X as Up
         if (Math.abs(direction.dot(worldUp)) > 0.9) {
             up.set(1, 0, 0);
         } else {
             up.copy(worldUp);
         }
         // Make up orthogonal to direction
         up.sub(direction.clone().multiplyScalar(up.dot(direction))).normalize();
    }

    const zAxis = new THREE.Vector3().crossVectors(direction, up);
    if (zAxis.lengthSq() < 0.0001) {
        // Fallback if up is parallel to direction
        zAxis.set(0, 0, 1);
        if (Math.abs(direction.dot(zAxis)) > 0.9) zAxis.set(1, 0, 0);
        zAxis.crossVectors(direction, zAxis);
    }
    zAxis.normalize();

    // Recalculate Up to ensure strict orthogonality
    up.crossVectors(zAxis, direction).normalize();

    const matrix = new THREE.Matrix4().makeBasis(direction, up, zAxis);
    return new THREE.Quaternion().setFromRotationMatrix(matrix);
};

// --- Types ---
type SnapType = 'none' | 'grid' | 'vertex' | 'midpoint' | 'edge' | 'face' | 'align' | 'endpoint';
type AlignmentLine = [THREE.Vector3, THREE.Vector3];

interface SnapResult {
    position: THREE.Vector3;
    type: SnapType;
    distance: number;
    snapObjectId?: string;
    snapEdge?: [THREE.Vector3, THREE.Vector3];
    normal?: THREE.Vector3;
}

interface InferenceGuide {
    type: 'x' | 'z';
    start: THREE.Vector3;
    end: THREE.Vector3;
}

type PushPullMode = 'top' | 'side' | 'none';

interface PushPullState {
    mode: PushPullMode;
    hoveredShapeId: string | null;
    hoveredEdgeIndex: number;
    dragStartPoint: THREE.Vector3 | null;
    originalHeight: number;
    originalPoints: IPoint[];
    normal: THREE.Vector3;
    dragHeight?: number;
}

interface RotateState {
    phase: 'hover' | 'set-start' | 'rotating';
    pivot: THREE.Vector3 | null;
    axis: THREE.Vector3 | null;
    startVector: THREE.Vector3 | null;
    currentAngle: number;
    initialTransforms: Record<string, { pos: THREE.Vector3, quat: THREE.Quaternion }>;
    lockedAxis: THREE.Vector3 | null;
}

interface ShapeRendererProps {
    shape: IShape;
    isSelected: boolean;
    pushPullState: PushPullState;
    pushPullHandlers: {
        handlePointerDown: (e: ThreeEvent<PointerEvent>) => void;
        handlePointerUp: () => void;
        handlePointerMove: (e: ThreeEvent<PointerEvent>) => void;
    };
    drawingHandlers: {
        handlePointerDown: (e: ThreeEvent<PointerEvent>) => void;
        handlePointerUp: (e: ThreeEvent<PointerEvent>) => void;
        handleClick: (e: ThreeEvent<MouseEvent>) => void;
    };
    rotateHandlers: {
        handleClick: (e: ThreeEvent<MouseEvent>) => void;
        handlePointerMove: (e: ThreeEvent<PointerEvent>) => void;
    };
    setDraggingState: (isDragging: boolean) => void;
    onShapeRef: (id: string, ref: THREE.Group | null) => void;
    shapeRefs: React.MutableRefObject<Record<string, THREE.Group | null>>;
    setAlignmentLines: (lines: AlignmentLine[]) => void;
}

// --- Geometry Helpers ---
const createThreeShape = (points: IPoint[]) => {
  const shape = new THREE.Shape();
  if (!points || points.length === 0) return shape;
  if (points[0]) {
    shape.moveTo(points[0].x, -points[0].z); 
    for (let i = 1; i < points.length; i++) {
        if (points[i]) shape.lineTo(points[i].x, -points[i].z);
    }
  }
  shape.closePath();
  return shape;
};

const createCirclePoints = (radius: number, segments = 32): IPoint[] => {
  const points: IPoint[] = [];
  for (let i = 0; i < segments; i++) {
    const theta = (i / segments) * Math.PI * 2;
    points.push({ x: Math.cos(theta) * radius, y: 0, z: Math.sin(theta) * radius });
  }
  points.push(points[0]);
  return points;
};

const transformPoint = (localP: IPoint, shape: IShape): THREE.Vector3 => {
    const v = new THREE.Vector3(localP.x, 0, localP.z);
    v.set(v.x * shape.scale[0], v.y * shape.scale[1], v.z * shape.scale[2]);
    const euler = new THREE.Euler(...shape.rotation);
    v.applyEuler(euler);
    v.add(new THREE.Vector3(...shape.position));
    return v;
};

const getShapeBounds = (shape: IShape, currentPos?: THREE.Vector3) => {
    const pos = currentPos || new THREE.Vector3(...shape.position);
    let minX = Infinity, maxX = -Infinity, minZ = Infinity, maxZ = -Infinity;
    const tempShape = { ...shape, position: [pos.x, pos.y, pos.z] as [number, number, number] };
    shape.points.forEach(p => {
         const wp = transformPoint(p, tempShape as IShape);
         if(wp.x < minX) minX = wp.x;
         if(wp.x > maxX) maxX = wp.x;
         if(wp.z < minZ) minZ = wp.z;
         if(wp.z > maxZ) maxZ = wp.z;
    });
    return { minX, maxX, minZ, maxZ, centerX: (minX + maxX) / 2, centerZ: (minZ + maxZ) / 2, y: pos.y };
};

const distToSegmentSquared = (p: THREE.Vector3, v: THREE.Vector3, w: THREE.Vector3) => {
    const l2 = v.distanceToSquared(w);
    if (l2 === 0) return p.distanceToSquared(v);
    let t = ((p.x - v.x) * (w.x - v.x) + (p.z - v.z) * (w.z - v.z)) / l2;
    t = Math.max(0, Math.min(1, t));
    return (p.x - (v.x + t * (w.x - v.x)))**2 + (p.z - (v.z + t * (w.z - v.z)))**2;
};

const getSegmentIntersection = (p1: IPoint, p2: IPoint, p3: IPoint, p4: IPoint): IPoint | null => {
    const d = (p2.x - p1.x) * (p4.z - p3.z) - (p2.z - p1.z) * (p4.x - p3.x);
    if (Math.abs(d) < 1e-9) return null; 

    const u = ((p3.x - p1.x) * (p4.z - p3.z) - (p3.z - p1.z) * (p4.x - p3.x)) / d;
    const v = ((p3.x - p1.x) * (p2.z - p1.z) - (p3.z - p1.z) * (p2.x - p1.x)) / d;

    const TOLERANCE = 1e-5;
    if (u >= -TOLERANCE && u <= 1 + TOLERANCE && v >= -TOLERANCE && v <= 1 + TOLERANCE) {
        return { 
            x: p1.x + u * (p2.x - p1.x), 
            y: 0, 
            z: p1.z + u * (p2.z - p1.z) 
        };
    }
    return null;
};

const isSamePoint = (p1: IPoint, p2: IPoint) => Math.abs(p1.x - p2.x) < 1e-4 && Math.abs(p1.z - p2.z) < 1e-4;

const cutPolygonBySegment = (polyPoints: IPoint[], lineStart: IPoint, lineEnd: IPoint): [IPoint[], IPoint[]] | null => {
    interface Intersection { 
        point: IPoint; 
        edgeIndex: number; 
        dist: number; 
    }
    const intersections: Intersection[] = [];

    for (let i = 0; i < polyPoints.length; i++) {
        const p1 = polyPoints[i];
        const p2 = polyPoints[(i + 1) % polyPoints.length];
        const hit = getSegmentIntersection(p1, p2, lineStart, lineEnd);
        if (hit) {
            const dist = Math.sqrt((hit.x - lineStart.x)**2 + (hit.z - lineStart.z)**2);
            const duplicate = intersections.find(int => isSamePoint(int.point, hit));
            if (!duplicate) {
                intersections.push({ point: hit, edgeIndex: i, dist });
            }
        }
    }

    if (intersections.length < 2) return null;

    intersections.sort((a, b) => a.dist - b.dist);

    const startHit = intersections[0];
    const endHit = intersections[intersections.length - 1];

    if (isSamePoint(startHit.point, endHit.point)) return null;

    const getPointsBetween = (startInt: Intersection, endInt: Intersection) => {
        const pts: IPoint[] = [startInt.point];
        let currIdx = startInt.edgeIndex;
        const stopEdgeIdx = endInt.edgeIndex;
        let loops = 0;

        while (currIdx !== stopEdgeIdx && loops < polyPoints.length * 2) {
            const nextVertexIdx = (currIdx + 1) % polyPoints.length;
            if (!isSamePoint(polyPoints[nextVertexIdx], startInt.point)) {
                pts.push(polyPoints[nextVertexIdx]);
            }
            currIdx = nextVertexIdx;
            loops++;
        }

        if (!isSamePoint(endInt.point, pts[pts.length - 1])) {
            pts.push(endInt.point);
        }
        return pts;
    };

    const polyA = getPointsBetween(startHit, endHit);
    const polyB = getPointsBetween(endHit, startHit);

    if (polyA.length < 3 || polyB.length < 3) return null;

    return [polyA, polyB];
};

const getLineEndpoints = (shape: IShape): [THREE.Vector3, THREE.Vector3] | null => {
    if (shape.name !== 'Edge' && shape.type !== 'line') return null;

    if (shape.points.length >= 2) {
        const p1 = transformPoint(shape.points[0], shape);
        const p2 = transformPoint(shape.points[1], shape);
        return [p1, p2];
    }

    return null;
};

const getGeometrySnap = (
    cursorPos: THREE.Vector3, 
    ray: THREE.Ray,
    shapes: IShape[], 
    activePoints: IPoint[] = [],
    threshold: number,
    intersectedObject?: THREE.Intersection
): SnapResult => {
    let fallbackSnap: SnapResult;
    const getShapeUserData = (obj: THREE.Object3D) => {
        if (obj.userData?.isShape) return obj.userData;
        if (obj.parent?.userData?.isShape) return obj.parent.userData;
        return null;
    };
    const shapeData = intersectedObject ? getShapeUserData(intersectedObject.object) : null;
    if (intersectedObject && shapeData) {
        let normal = new THREE.Vector3(0, 1, 0);
        if (intersectedObject.face) {
            const normalMatrix = new THREE.Matrix3().getNormalMatrix(intersectedObject.object.matrixWorld);
            normal = intersectedObject.face.normal.clone().applyMatrix3(normalMatrix).normalize();
        }
        fallbackSnap = { position: intersectedObject.point, type: 'face', distance: 0, snapObjectId: shapeData.id, normal };
    } else {
        fallbackSnap = {
            position: new THREE.Vector3(Math.round(cursorPos.x / SNAP_GRID) * SNAP_GRID, cursorPos.y, Math.round(cursorPos.z / SNAP_GRID) * SNAP_GRID),
            type: 'grid', distance: Infinity, normal: new THREE.Vector3(0, 1, 0)
        };
    }
    let bestVertexSnap: SnapResult | null = null;
    let bestEdgeSnap: SnapResult | null = null;
    let minVertexDist = threshold;
    let minEdgeDist = threshold;

    // Check loop closure snap
    if (activePoints && activePoints.length > 0) {
        const startPt = activePoints[0];
        const ptVec = new THREE.Vector3(startPt.x, startPt.y, startPt.z);
        const dist = ray.distanceToPoint(ptVec);
        if (dist < threshold * 1.5) {
            bestVertexSnap = { position: ptVec, type: 'endpoint', distance: dist, normal: new THREE.Vector3(0,1,0) };
            minVertexDist = dist;
        }
    }

    for (const shape of shapes) {
        // PERFORMANCE OPTIMIZATION: Distance Culling
        const shapePos = new THREE.Vector3(...shape.position);
        if (shapePos.distanceTo(cursorPos) > SNAP_CULLING_DISTANCE) {
            continue;
        }

        if (shape.type === 'line' || shape.name === 'Edge') {
             const endpoints = getLineEndpoints(shape);
             if (endpoints) {
                 const edgeVec = new THREE.Vector3().subVectors(endpoints[1], endpoints[0]).normalize();
                 for(const ep of endpoints) {
                     const dist = ray.distanceToPoint(ep);
                     if (dist < minVertexDist) {
                         bestVertexSnap = { position: ep, type: 'endpoint', distance: dist, snapObjectId: shape.id, normal: edgeVec };
                         minVertexDist = dist;
                     }
                 }
                 continue; 
             }
        }
        const currentH = shape.height * shape.scale[1];
        const hasHeight = Math.abs(currentH) > 0.001;
        for (let i = 0; i < shape.points.length; i++) {
            const worldPt = transformPoint(shape.points[i], shape);
            let dist = ray.distanceToPoint(worldPt);
            if (dist < minVertexDist) {
                bestVertexSnap = { position: worldPt, type: 'vertex', distance: dist, snapObjectId: shape.id, normal: new THREE.Vector3(0,1,0) };
                minVertexDist = dist;
            }
            if (hasHeight) {
                const worldPtTop = transformPoint(shape.points[i], { ...shape, position: [shape.position[0], shape.position[1] + currentH, shape.position[2]] });
                dist = ray.distanceToPoint(worldPtTop);
                if (dist < minVertexDist) {
                    bestVertexSnap = { position: worldPtTop, type: 'vertex', distance: dist, snapObjectId: shape.id, normal: new THREE.Vector3(0,1,0) };
                    minVertexDist = dist;
                }
            }
        }
    }

    // Only check edges if we haven't found a very close vertex
    if (!bestVertexSnap || bestVertexSnap.distance > 0.1) {
        for (const shape of shapes) {
            // PERFORMANCE OPTIMIZATION: Distance Culling
            const shapePos = new THREE.Vector3(...shape.position);
            if (shapePos.distanceTo(cursorPos) > SNAP_CULLING_DISTANCE) {
                continue;
            }

            const pts = shape.points;
            const len = pts.length;
            const currentH = shape.height * shape.scale[1];
            const hasHeight = Math.abs(currentH) > 0.001;
            const getWorldPos = (localX: number, localY: number, localZ: number) => {
                 const v = new THREE.Vector3(localX, localY, localZ);
                 v.set(v.x * shape.scale[0], v.y * shape.scale[1], v.z * shape.scale[2]);
                 v.applyEuler(new THREE.Euler(...shape.rotation));
                 v.add(new THREE.Vector3(...shape.position));
                 return v;
            }
            for (let i = 0; i < len; i++) {
                const p1 = getWorldPos(pts[i].x, 0, pts[i].z);
                const p2 = getWorldPos(pts[(i + 1) % len].x, 0, pts[(i + 1) % len].z);
                const checkSegment = (v1: THREE.Vector3, v2: THREE.Vector3) => {
                    const mid = new THREE.Vector3().addVectors(v1, v2).multiplyScalar(0.5);
                    const distMid = ray.distanceToPoint(mid);
                    const edgeVec = new THREE.Vector3().subVectors(v2, v1).normalize();
                    if (distMid < minEdgeDist) {
                        bestEdgeSnap = { position: mid, type: 'midpoint', distance: distMid, snapObjectId: shape.id, snapEdge: [v1, v2], normal: edgeVec };
                        minEdgeDist = distMid;
                    }
                    const pointOnSegment = new THREE.Vector3();
                    const distSq = ray.distanceSqToSegment(v1, v2, undefined, pointOnSegment);
                    const distEdge = Math.sqrt(distSq);
                    if (distEdge < minEdgeDist) {
                         if (bestEdgeSnap?.type === 'midpoint' && bestEdgeSnap.distance < distEdge + 0.1) {} else {
                             bestEdgeSnap = { position: pointOnSegment, type: 'edge', distance: distEdge, snapObjectId: shape.id, snapEdge: [v1, v2], normal: edgeVec };
                             minEdgeDist = distEdge;
                         }
                    }
                };
                checkSegment(p1, p2);
                if (hasHeight) {
                    const p1Top = getWorldPos(pts[i].x, shape.height, pts[i].z);
                    const p2Top = getWorldPos(pts[(i + 1) % len].x, shape.height, pts[(i + 1) % len].z);
                    checkSegment(p1Top, p2Top); checkSegment(p1, p1Top);
                }
            }
        }
    }
    if (bestVertexSnap && bestEdgeSnap) {
        if (bestVertexSnap.distance < bestEdgeSnap.distance * 1.5) return bestVertexSnap;
        else return bestEdgeSnap;
    }
    if (bestVertexSnap) return bestVertexSnap;
    if (bestEdgeSnap) return bestEdgeSnap;
    return fallbackSnap;
};

// ... Components ...

const SimpleLine: React.FC<{ points: (THREE.Vector3 | [number, number, number])[], color: string, dashed?: boolean, opacity?: number, transparent?: boolean, lineWidth?: number, depthTest?: boolean }> = ({ points, color, dashed, opacity, transparent, lineWidth, depthTest = true }) => {
    const ref = useRef<THREE.Line>(null);
    const geometry = useMemo(() => {
        const pts = points.map(p => (p instanceof THREE.Vector3 ? p : new THREE.Vector3(...p)));
        return new THREE.BufferGeometry().setFromPoints(pts);
    }, [points]);
    useLayoutEffect(() => {
        if (dashed && ref.current) ref.current.computeLineDistances();
    }, [geometry, dashed]);
    return (
        <line ref={ref as any} geometry={geometry}>
            {dashed ? ( <lineDashedMaterial color={color} dashSize={0.2} gapSize={0.1} transparent={transparent} opacity={opacity} depthTest={depthTest} toneMapped={false} /> ) : ( <lineBasicMaterial color={color} transparent={transparent} opacity={opacity} depthTest={depthTest} toneMapped={false} /> )}
        </line>
    );
};

const InferenceGuideRenderer: React.FC<{ guide: InferenceGuide | null }> = ({ guide }) => {
    if (!guide) return null;
    const color = guide.type === 'x' ? '#ef4444' : '#22c55e'; // Red for X, Green for Z
    return (
         <SimpleLine 
            points={[guide.start, guide.end]} 
            color={color} 
            lineWidth={2} 
            depthTest={false} 
            opacity={0.8} 
        />
    );
};

const GuideLinesRenderer: React.FC<{ lines: IGuideLine[] }> = ({ lines }) => {
    if (lines.length === 0) return null;

    return (
        <group renderOrder={9999}>
            {lines.map((line) => {
                const p1 = new THREE.Vector3(...line.points[0]);
                const p2 = new THREE.Vector3(...line.points[1]);
                const dir = new THREE.Vector3().subVectors(p2, p1).normalize();

                const start = p1.clone().add(dir.clone().multiplyScalar(-1000));
                const end = p1.clone().add(dir.clone().multiplyScalar(1000));

                return (
                    <SimpleLine 
                        key={line.id} 
                        points={[start, end]} 
                        color="#a855f7" 
                        dashed 
                        lineWidth={1} 
                        depthTest={false} 
                        opacity={0.8} 
                    />
                );
            })}
        </group>
    );
};

const DimensionShape: React.FC<{ shape: IShape; isSelected: boolean; onSelect: (e: ThreeEvent<MouseEvent>) => void }> = ({ shape, isSelected, onSelect }) => {
    const { formatValue, tool, updateShape } = useApp();
    const { camera, gl } = useThree();
    const [dragP3, setDragP3] = useState<THREE.Vector3 | null>(null);
    const draggingRef = useRef(false);
    const rafRef = useRef<number | null>(null);

    if (!shape.points || shape.points.length < 3) return null;

    const p1 = new THREE.Vector3(shape.points[0].x, shape.points[0].y, shape.points[0].z);
    const p2 = new THREE.Vector3(shape.points[1].x, shape.points[1].y, shape.points[1].z);

    const p3Source = dragP3 || new THREE.Vector3(shape.points[2].x, shape.points[2].y, shape.points[2].z);

    const v12 = new THREE.Vector3().subVectors(p2, p1);
    const v13 = new THREE.Vector3().subVectors(p3Source, p1);
    const projection = v13.dot(v12) / v12.lengthSq();
    const projectedPoint = p1.clone().add(v12.multiplyScalar(projection));
    const offsetVector = new THREE.Vector3().subVectors(p3Source, projectedPoint);

    const dimStart = p1.clone().add(offsetVector);
    const dimEnd = p2.clone().add(offsetVector);
    const midPoint = new THREE.Vector3().addVectors(dimStart, dimEnd).multiplyScalar(0.5);

    const GAP_SIZE = 0.05; 
    const offsetDir = offsetVector.clone().normalize();
    const offsetLen = offsetVector.length();

    const useGap = offsetLen > GAP_SIZE * 1.5;
    const ext1Start = useGap ? p1.clone().add(offsetDir.clone().multiplyScalar(GAP_SIZE)) : p1;
    const ext2Start = useGap ? p2.clone().add(offsetDir.clone().multiplyScalar(GAP_SIZE)) : p2;

    const color = isSelected ? '#3b82f6' : (shape.color || '#333');

    const handlePointerDown = (e: ThreeEvent<PointerEvent>) => {
        if (tool === ToolType.SELECT && isSelected && e.button === 0) {
            e.stopPropagation();
            draggingRef.current = true;
            document.body.style.cursor = 'grabbing';

            const handleWindowMove = (ev: PointerEvent) => {
                if (!draggingRef.current) return;

                // Use requestAnimationFrame for smoother drag updates to avoid blocking the main thread
                if (rafRef.current) cancelAnimationFrame(rafRef.current);
                rafRef.current = requestAnimationFrame(() => {
                    const raycaster = new THREE.Raycaster();
                    const ndc = new THREE.Vector2(
                        (ev.clientX / gl.domElement.clientWidth) * 2 - 1,
                        -(ev.clientY / gl.domElement.clientHeight) * 2 + 1
                    );
                    raycaster.setFromCamera(ndc, camera);

                    const planeY = p1.y;
                    const plane = new THREE.Plane(new THREE.Vector3(0, 1, 0), -planeY);
                    const target = new THREE.Vector3();

                    if (raycaster.ray.intersectPlane(plane, target)) {
                        setDragP3(target);
                    }
                });
            };

            const handleWindowUp = () => {
                if (draggingRef.current) {
                    draggingRef.current = false;
                    document.body.style.cursor = 'default';
                    window.removeEventListener('pointermove', handleWindowMove);
                    window.removeEventListener('pointerup', handleWindowUp);
                    if (rafRef.current) cancelAnimationFrame(rafRef.current);

                    setDragP3((finalP3) => {
                        if (finalP3) {
                            const newPoints = [shape.points[0], shape.points[1], { x: finalP3.x, y: finalP3.y, z: finalP3.z }];
                            updateShape(shape.id, { points: newPoints });
                        }
                        return null; 
                    });
                }
            };

            window.addEventListener('pointermove', handleWindowMove);
            window.addEventListener('pointerup', handleWindowUp);
        } else {
            e.stopPropagation();
            onSelect(e);
        }
    };

    const quaternion = useMemo(() => getDimensionRotation(dimStart, dimEnd, offsetVector), [dimStart, dimEnd, offsetVector]);

    return (
        <group 
            onPointerDown={handlePointerDown}
            position={shape.position} 
            rotation={shape.rotation} 
            scale={shape.scale}
        >
            <SimpleLine points={[dimStart, dimEnd]} color={color} depthTest={false} />
            <SimpleLine points={[ext1Start, dimStart]} color="#999" dashed depthTest={false} />
            <SimpleLine points={[ext2Start, dimEnd]} color="#999" dashed depthTest={false} />
            <mesh position={dimStart}><sphereGeometry args={[0.03]} /><meshBasicMaterial color={color} depthTest={false} /></mesh>
            <mesh position={dimEnd}><sphereGeometry args={[0.03]} /><meshBasicMaterial color={color} depthTest={false} /></mesh>
            <Text 
                position={midPoint}
                quaternion={quaternion}
                fontSize={0.25} 
                color={color} 
                anchorX="center" 
                anchorY="bottom" 
                outlineWidth={0.02} 
                outlineColor="#ffffff" 
                depthTest={false}
                renderOrder={1000}
            >
                {formatValue(p1.distanceTo(p2))}
            </Text>
        </group>
    );
};

const AlignmentLinesRenderer: React.FC<{ lines: AlignmentLine[] }> = ({ lines }) => {
    if (lines.length === 0) return null;
    return ( <group>{lines.map((line, i) => (<SimpleLine key={i} points={line} color="red" dashed lineWidth={2} depthTest={false} opacity={0.8} />))}</group> );
};

const SnapIndicator: React.FC<{ position: THREE.Vector3; type: SnapType; snapEdge?: [THREE.Vector3, THREE.Vector3] }> = ({ position, type, snapEdge }) => {
    if (type === 'grid' || type === 'none') return null;
    let color = '#f59e0b'; let size = 0.08; let geometry = <sphereGeometry args={[size]} />;
    if (type === 'endpoint' || type === 'vertex') { color = '#10b981'; size = 0.12; geometry = <sphereGeometry args={[size]} />; } 
    else if (type === 'midpoint') { color = '#06b6d4'; size = 0.1; geometry = <coneGeometry args={[size, size * 2, 4]} />; } 
    else if (type === 'edge') { color = '#ef4444'; size = 0.06; geometry = <boxGeometry args={[size * 1.5, size * 1.5, size * 1.5]} />; } 
    else if (type === 'face') { color = '#3b82f6'; }
    return (
        <group position={position}>
            {type === 'face' ? ( <mesh rotation={[-Math.PI/2, 0, 0]}><planeGeometry args={[0.2, 0.2]} /><meshBasicMaterial color={color} depthTest={false} transparent opacity={0.5} side={THREE.DoubleSide} /><lineSegments><edgesGeometry args={[new THREE.PlaneGeometry(0.2, 0.2)]} /><lineBasicMaterial color={color} depthTest={false} /></lineSegments></mesh> ) : ( <mesh>{geometry}<meshBasicMaterial color={color} depthTest={false} /></mesh> )}
            {type === 'edge' && snapEdge && (<SimpleLine points={[snapEdge[0], snapEdge[1]]} color="#ef4444" lineWidth={3} depthTest={false} />)}
            {type === 'midpoint' && snapEdge && (<SimpleLine points={[snapEdge[0], snapEdge[1]]} color="#06b6d4" lineWidth={3} depthTest={false} />)}
        </group>
    );
};

const CursorTooltip: React.FC<{ text: string; position: THREE.Vector3; type?: SnapType }> = ({ text, position, type }) => {
    if (type === 'grid' || type === 'none') return null;
    let displayType = ''; let bgColor = 'bg-slate-900/80'; let textColor = 'text-white';
    switch(type) {
        case 'vertex': displayType = '節點 (Node)'; bgColor = 'bg-emerald-600'; break;
        case 'endpoint': displayType = '端點 (Endpoint)'; bgColor = 'bg-emerald-600'; break;
        case 'midpoint': displayType = '中點 (Midpoint)'; bgColor = 'bg-cyan-600'; break;
        case 'edge': displayType = '邊緣 (Edge)'; bgColor = 'bg-red-500'; break;
        case 'face': displayType = '表面 (Face)'; bgColor = 'bg-blue-600'; break;
        case 'align': displayType = '對齊 (Align)'; bgColor = 'bg-pink-500'; break;
        default: displayType = '';
    }
    const displayText = displayType ? (text ? `${displayType}: ${text}` : displayType) : text;
    return (
        <Html position={[position.x, position.y + 0.5, position.z]} center style={{ pointerEvents: 'none', zIndex: 100 }}>
            <div className={`${bgColor} ${textColor} text-xs px-3 py-1.5 rounded-full shadow-lg backdrop-blur-sm border border-white/20 whitespace-nowrap flex items-center gap-2 font-bold transform -translate-y-2`}>{displayText}</div>
        </Html>
    );
};

const useShapeDrag = (
    shape: IShape,
    shapes: IShape[],
    isSelected: boolean,
    tool: ToolType,
    updateShapes: (updates: { id: string; changes: Partial<IShape> }[]) => void,
    setDraggingState: (isDragging: boolean) => void,
    selectedIds: string[],
    shapeRefs: React.MutableRefObject<Record<string, THREE.Group | null>>,
    setAlignmentLines: (lines: AlignmentLine[]) => void
) => {
    const { camera, gl } = useThree();
    const groupRef = useRef<THREE.Group>(null);
    const dragInfo = useRef({ startPoint: new THREE.Vector3(), originalPositions: {} as Record<string, THREE.Vector3>, isDragging: false });
    const getGroundIntersection = (clientX: number, clientY: number) => {
        const plane = new THREE.Plane(new THREE.Vector3(0, 1, 0), 0);
        const raycaster = new THREE.Raycaster();
        const ndc = new THREE.Vector2((clientX / gl.domElement.clientWidth) * 2 - 1, -(clientY / gl.domElement.clientHeight) * 2 + 1);
        raycaster.setFromCamera(ndc, camera);
        const target = new THREE.Vector3();
        const hit = raycaster.ray.intersectPlane(plane, target);
        return hit ? target : null;
    };
    const handlePointerMove = useCallback((e: PointerEvent) => {
        if (!dragInfo.current.isDragging) return;
        const intersect = getGroundIntersection(e.clientX, e.clientY);
        if (intersect) {
             const rawDelta = new THREE.Vector3().subVectors(intersect, dragInfo.current.startPoint);
             const myOriginalPos = dragInfo.current.originalPositions[shape.id];
             if (!myOriginalPos) return;
             const targetPos = new THREE.Vector3().addVectors(myOriginalPos, rawDelta);
             let snappedX = Math.round(targetPos.x / SNAP_GRID) * SNAP_GRID;
             let snappedZ = Math.round(targetPos.z / SNAP_GRID) * SNAP_GRID;
             const newLines: AlignmentLine[] = [];
             const myBoundsRaw = getShapeBounds(shape, new THREE.Vector3(targetPos.x, myOriginalPos.y, targetPos.z));
             let bestXDist = 0.3; let bestXVal: number | null = null; let xMatchLine: AlignmentLine | null = null;
             let bestZDist = 0.3; let bestZVal: number | null = null; let zMatchLine: AlignmentLine | null = null;
             for (const other of shapes) {
                 if (selectedIds.includes(other.id)) continue;
                 const otherBounds = getShapeBounds(other);
                 const xSources = [myBoundsRaw.centerX, myBoundsRaw.minX, myBoundsRaw.maxX];
                 const xTargets = [otherBounds.centerX, otherBounds.minX, otherBounds.maxX];
                 for (const src of xSources) {
                     for (const tgt of xTargets) {
                         const dist = Math.abs(src - tgt);
                         if (dist < bestXDist) { bestXDist = dist; bestXVal = targetPos.x - (src - tgt); const minZ = Math.min(myBoundsRaw.minZ, otherBounds.minZ) - 1; const maxZ = Math.max(myBoundsRaw.maxZ, otherBounds.maxZ) + 1; xMatchLine = [ new THREE.Vector3(tgt, 0, minZ), new THREE.Vector3(tgt, 0, maxZ) ]; }
                     }
                 }
                 const zSources = [myBoundsRaw.centerZ, myBoundsRaw.minZ, myBoundsRaw.maxZ];
                 const zTargets = [otherBounds.centerZ, otherBounds.minZ, otherBounds.maxZ];
                 for (const src of zSources) {
                     for (const tgt of zTargets) {
                         const dist = Math.abs(src - tgt);
                         if (dist < bestZDist) { bestZDist = dist; bestZVal = targetPos.z - (src - tgt); const minX = Math.min(myBoundsRaw.minX, otherBounds.minX) - 1; const maxX = Math.max(myBoundsRaw.maxX, otherBounds.maxX) + 1; zMatchLine = [ new THREE.Vector3(minX, 0, tgt), new THREE.Vector3(maxX, 0, tgt) ]; }
                     }
                 }
             }
             if (bestXVal !== null) { snappedX = bestXVal; if (xMatchLine) newLines.push(xMatchLine); }
             if (bestZVal !== null) { snappedZ = bestZVal; if (zMatchLine) newLines.push(zMatchLine); }
             setAlignmentLines(newLines);
             const snappedPos = new THREE.Vector3(snappedX, myOriginalPos.y, snappedZ);
             const effectiveDelta = new THREE.Vector3().subVectors(snappedPos, myOriginalPos);
             Object.entries(dragInfo.current.originalPositions).forEach(([id, origPos]) => {
                 const ref = shapeRefs.current[id];
                 if (ref) { ref.position.copy(origPos).add(effectiveDelta); }
             });
        }
    }, [camera, gl, shape.id, shapes, selectedIds]);
    const handlePointerUp = useCallback((e: PointerEvent) => {
        if (!dragInfo.current.isDragging) return;
        document.body.style.cursor = 'default';
        dragInfo.current.isDragging = false;
        setDraggingState(false);
        setAlignmentLines([]);
        window.removeEventListener('pointermove', handlePointerMove);
        window.removeEventListener('pointerup', handlePointerUp);
        const updates = Object.keys(dragInfo.current.originalPositions).map(id => {
            const ref = shapeRefs.current[id];
            if (ref) { return { id, changes: { position: [ref.position.x, ref.position.y, ref.position.z] as [number, number, number] } }; }
            return null;
        }).filter(Boolean) as { id: string, changes: Partial<IShape> }[];
        if (updates.length > 0) updateShapes(updates);
    }, [handlePointerMove, updateShapes, setDraggingState, setAlignmentLines]);
    const handlePointerDown = useCallback((e: ThreeEvent<PointerEvent>) => {
        if (tool !== ToolType.SELECT || e.button !== 0) return;
        e.stopPropagation();
        const intersect = getGroundIntersection(e.clientX, e.clientY);
        if (intersect && groupRef.current) {
            dragInfo.current.isDragging = true;
            dragInfo.current.startPoint.copy(intersect);
            let idsToMove: string[] = [];
            if (isSelected) idsToMove = [...selectedIds]; else { if (shape.groupId) idsToMove = shapes.filter(s => s.groupId === shape.groupId).map(s => s.id); else idsToMove = [shape.id]; }
            if (!idsToMove.includes(shape.id)) idsToMove.push(shape.id);
            const origins: Record<string, THREE.Vector3> = {};
            idsToMove.forEach(id => { const ref = shapeRefs.current[id]; if (ref) origins[id] = ref.position.clone(); });
            dragInfo.current.originalPositions = origins;
            document.body.style.cursor = 'move';
            setDraggingState(true);
            window.addEventListener('pointermove', handlePointerMove);
            window.addEventListener('pointerup', handlePointerUp);
        }
    }, [tool, shape, shapes, camera, gl, handlePointerMove, handlePointerUp, setDraggingState, isSelected, selectedIds]);
    useEffect(() => { return () => { window.removeEventListener('pointermove', handlePointerMove); window.removeEventListener('pointerup', handlePointerUp); }; }, [handlePointerMove, handlePointerUp]);
    return { groupRef, handlePointerDown };
};

const ShapeRenderer = React.memo(({ shape, isSelected, pushPullState, pushPullHandlers, drawingHandlers, rotateHandlers, setDraggingState, onShapeRef, shapeRefs, setAlignmentLines }: ShapeRendererProps) => {
    const { unit, tool, updateShapes, layers, selectedIds, shapes, selectShape, updateShape } = useApp();
    const parentLayer = layers.find(l => l.id === shape.layerId);

    const handleSelect = useCallback((e: ThreeEvent<MouseEvent>) => {
        e.stopPropagation();
        const isMulti = e.nativeEvent.ctrlKey || e.nativeEvent.metaKey || e.nativeEvent.shiftKey;
        selectShape(shape.id, isMulti);
    }, [selectShape, shape.id]);

    const dimensionSelect = useCallback((e: ThreeEvent<MouseEvent>) => {
        if (!isSelected) {
             e.stopPropagation();
             selectShape(shape.id, e.nativeEvent.ctrlKey || e.nativeEvent.metaKey || e.nativeEvent.shiftKey);
        }
    }, [isSelected, selectShape, shape.id]);

    if (parentLayer && !parentLayer.visible) return null;

    if (shape.type === 'dimension') { 
        return <DimensionShape shape={shape} isSelected={isSelected} onSelect={dimensionSelect} />; 
    }

    if (shape.type === 'text') {
        const { groupRef, handlePointerDown } = useShapeDrag(shape, shapes, isSelected, tool, updateShapes, setDraggingState, selectedIds, shapeRefs, setAlignmentLines);

        useLayoutEffect(() => { 
            onShapeRef(shape.id, groupRef.current); 
            return () => onShapeRef(shape.id, null); 
        }, [onShapeRef, shape.id]);

        return (
            <group
                ref={groupRef}
                position={shape.position}
                rotation={new THREE.Euler(...shape.rotation)}
                scale={shape.scale}
                onClick={(e) => { 
                    if (tool === ToolType.SELECT) handleSelect(e);
                }}
                onPointerDown={(e) => {
                     if (tool === ToolType.SELECT) { if (!isSelected) handleSelect(e); handlePointerDown(e); }
                     else if (tool === ToolType.ROTATE) rotateHandlers.handleClick(e);
                }}
            >
                <Text
                    fontSize={shape.fontSize || 0.5}
                    color={shape.color}
                    anchorX="center"
                    anchorY="middle"
                    outlineWidth={isSelected ? 0.02 : 0}
                    outlineColor="#3b82f6"
                >
                    {shape.content || 'Text'}
                </Text>
            </group>
        );
    }

    if (shape.type === 'line') {
         if (shape.points.length < 2) return null;
         const p1 = transformPoint(shape.points[0], shape);
         const p2 = transformPoint(shape.points[1], shape);
         return (
             <group 
                position={[0, 0, 0]} 
                onClick={(e) => { 
                    if (tool === ToolType.SELECT) handleSelect(e);
                }}
             >
                <SimpleLine points={[p1, p2]} color={isSelected ? '#3b82f6' : 'black'} lineWidth={2} />
             </group>
         );
    }

    const isPushPullMode = tool === ToolType.PUSH_PULL;
    const highlightColor = shape.color;
    const edgeColor = isSelected ? '#3b82f6' : '#333';
    const emissiveColor = isSelected ? '#3b82f6' : '#000000';
    const emissiveIntensity = isSelected ? 0.2 : 0;

    const { groupRef, handlePointerDown } = useShapeDrag(shape, shapes, isSelected, tool, updateShapes, setDraggingState, selectedIds, shapeRefs, setAlignmentLines);

    useLayoutEffect(() => { 
        onShapeRef(shape.id, groupRef.current); 
        return () => onShapeRef(shape.id, null); 
    }, [onShapeRef, shape.id]);

    const isDraggingTop = pushPullState.mode === 'top' && pushPullState.hoveredShapeId === shape.id && !!pushPullState.dragStartPoint;
    let scaleY = 1;
    if (isDraggingTop && pushPullState.dragHeight !== undefined && shape.height > 0) scaleY = pushPullState.dragHeight / shape.height;

    const shape2D = useMemo(() => createThreeShape(shape.points), [shape.points]);
    const geometry = useMemo(() => new THREE.ExtrudeGeometry(shape2D, { depth: shape.height, bevelEnabled: false }), [shape2D, shape.height]);

    return (
        <group 
            ref={groupRef}
            position={[shape.position[0], shape.position[1], shape.position[2]]} 
            rotation={new THREE.Euler(...shape.rotation)} 
            scale={[shape.scale[0], shape.scale[1] * scaleY, shape.scale[2]]} 
            userData={{ isShape: true, id: shape.id, isContainer: true }} 
            name="shape_group" 
            onPointerDown={(e) => {
                if (isPushPullMode) pushPullHandlers.handlePointerDown(e);
                else if (tool === ToolType.SELECT) { if (!isSelected) handleSelect(e); handlePointerDown(e); }
                else if (tool === ToolType.ROTATE) rotateHandlers.handleClick(e);
                else drawingHandlers.handlePointerDown(e);
            }}
            onPointerMove={(e) => { if (isPushPullMode) pushPullHandlers.handlePointerMove(e); }}
            onPointerUp={(e) => { if (isPushPullMode) pushPullHandlers.handlePointerUp(); else drawingHandlers.handlePointerUp(e); }}
        >
            <mesh 
                rotation={[-Math.PI/2, 0, 0]} 
                castShadow 
                receiveShadow 
                userData={{ isShape: true, id: shape.id }}
                geometry={geometry}
            >
                <meshStandardMaterial color={highlightColor} emissive={emissiveColor} emissiveIntensity={emissiveIntensity} transparent={shape.type === 'flat'} opacity={shape.type === 'flat' ? 0.6 : 1.0} polygonOffset={shape.type === 'flat'} polygonOffsetFactor={shape.type === 'flat' ? -1 : 0} />
                {!isPushPullMode && (
                    <lineSegments>
                        <edgesGeometry args={[geometry, 15]} />
                        <lineBasicMaterial color={edgeColor} toneMapped={false} />
                    </lineSegments>
                )}
            </mesh>
        </group>
    );
});

// ... Gizmo & Helper Components ...
const SelectionGizmo: React.FC<{ setDragging: (active: boolean) => void }> = ({ setDragging }) => {
    const { selectedIds, transformMode, updateShape, tool } = useApp();
    const { scene, camera } = useThree();
    const [targetObj, setTargetObj] = useState<THREE.Object3D | null>(null);
    const isEnabled = (tool === ToolType.SELECT || tool === ToolType.ROTATE) && selectedIds.length === 1;
    const selectedId = isEnabled ? selectedIds[0] : null;
    const activeMode = tool === ToolType.ROTATE ? 'rotate' : transformMode;
    useFrame(() => {
        if (!isEnabled || !selectedId) { if (targetObj) setTargetObj(null); return; }
        if (targetObj && targetObj.userData?.id === selectedId) return;
        let found: THREE.Object3D | null = null;
        scene.traverse((child) => { if (found) return; if (child.userData?.isShape && child.userData?.id === selectedId && child.userData?.isContainer) found = child; });
        if (found && found !== targetObj) setTargetObj(found);
    });
    if (!isEnabled || !targetObj) return null;
    return ( 
        <TransformControls 
            object={targetObj} 
            mode={activeMode} 
            space={activeMode === 'scale' ? 'local' : 'world'} 
            {...({ onDraggingChange: (isDragging: boolean) => { setDragging(isDragging); } } as any)}
            onMouseUp={() => { if (targetObj) updateShape(selectedId!, { position: [targetObj.position.x, targetObj.position.y, targetObj.position.z], rotation: [targetObj.rotation.x, targetObj.rotation.y, targetObj.rotation.z], scale: [targetObj.scale.x, targetObj.scale.y, targetObj.scale.z] }); }} 
        /> 
    );
};

const CameraHandler: React.FC<{ view: string | null; onFinished: () => void }> = ({ view, onFinished }) => {
    const { camera, controls } = useThree();
    useEffect(() => {
        if (!view) return;
        let targetPos = new THREE.Vector3();
        const DISTANCE = 20;
        switch (view) { case 'top': targetPos.set(0, DISTANCE, 0); break; case 'bottom': targetPos.set(0, -DISTANCE, 0); break; case 'front': targetPos.set(0, 0, DISTANCE); break; case 'back': targetPos.set(0, 0, -DISTANCE); break; case 'right': targetPos.set(DISTANCE, 0, 0); break; case 'left': targetPos.set(-DISTANCE, 0, 0); break; default: return; }
        camera.position.copy(targetPos);
        camera.lookAt(0, 0, 0);
        if (controls) { const c = controls as any; if (c.target && typeof c.target.set === 'function') { c.target.set(0, 0, 0); c.update(); } }
        onFinished();
    }, [view, camera, controls, onFinished]);
    return null;
};

// ... Interaction Layer ...
const DrawingPreview: React.FC<{ tool: ToolType; points: IPoint[]; cursorPos: THREE.Vector3; guideCreating: { active: boolean, start: THREE.Vector3, current: THREE.Vector3, edge: [THREE.Vector3, THREE.Vector3] | null }; drawingNormal: THREE.Vector3 }> = ({ tool, points, cursorPos, guideCreating, drawingNormal }) => {
    const { formatValue } = useApp();
    const currentPoint = cursorPos;
    if ((tool === ToolType.MEASURE || tool === ToolType.GUIDE_LINE) && guideCreating.active) {
        // ... (Same guide creation logic)
        if (guideCreating.edge) {
            const p1 = guideCreating.edge[0]; const p2 = guideCreating.edge[1];
            const direction = new THREE.Vector3().subVectors(p2, p1).normalize();
            const lineStart = guideCreating.current.clone().sub(direction.clone().multiplyScalar(100));
            const lineEnd = guideCreating.current.clone().add(direction.clone().multiplyScalar(100));
            const edgeVec = new THREE.Vector3().subVectors(p2, p1);
            const pointVec = new THREE.Vector3().subVectors(guideCreating.current, p1);
            const projected = p1.clone().add(edgeVec.clone().multiplyScalar(pointVec.dot(edgeVec) / edgeVec.lengthSq()));
            const dist = guideCreating.current.distanceTo(projected);
            return ( 
                <group>
                    <SimpleLine points={[lineStart, lineEnd]} color="#a855f7" dashed opacity={0.6} />
                    <Billboard position={[guideCreating.current.x, guideCreating.current.y + 0.2, guideCreating.current.z]}>
                        <Text fontSize={0.25} color="#a855f7" anchorX="center" anchorY="middle" outlineWidth={0.03} outlineColor="#fff">
                            {formatValue(dist)}
                        </Text>
                    </Billboard>
                </group> 
            );
        } else if (tool === ToolType.GUIDE_LINE) {
            // ... (Same axis guide logic)
            const dx = Math.abs(guideCreating.current.x - guideCreating.start.x);
            const dz = Math.abs(guideCreating.current.z - guideCreating.start.z);
            let start = guideCreating.start.clone();
            let end = guideCreating.current.clone();
            if (dx > dz) { end.z = start.z; start.x -= 100; end.x += 100; } else { end.x = start.x; start.z -= 100; end.z += 100; }
             return ( <group><SimpleLine points={[start, end]} color="#a855f7" dashed opacity={0.6} /></group> );
        }
    }

    // --- DIMENSION & MEASURE TOOL PREVIEW (Unified 3-point logic with offset) ---
    if ((tool === ToolType.DIMENSION || tool === ToolType.MEASURE) && points.length > 0) {
        // Phase 1: Start -> Cursor (Waiting for 2nd point)
        if (points.length === 1) {
            const start = new THREE.Vector3(points[0].x, points[0].y, points[0].z);
            const dist = start.distanceTo(currentPoint);
            const mid = start.clone().add(currentPoint).multiplyScalar(0.5);

            // Default offset to align text with the line on the surface defined by drawingNormal
            // Z=drawingNormal, X=direction, Y=offset(up)
            const direction = new THREE.Vector3().subVectors(currentPoint, start).normalize();
            const offsetVector = drawingNormal ? drawingNormal.clone().cross(direction) : new THREE.Vector3(0, 1, 0);

            // Just use a simple up for now if no normal, e.g. Y up
            if (!drawingNormal && Math.abs(direction.y) < 0.9) offsetVector.set(0, 1, 0);

            const rotation = getDimensionRotation(start, currentPoint, offsetVector);

            return (
                <group>
                    <SimpleLine points={[start, currentPoint]} color={tool === ToolType.DIMENSION ? "#3b82f6" : "#ec4899"} dashed opacity={0.7} />
                    <Text 
                        position={mid}
                        quaternion={rotation}
                        fontSize={0.25} 
                        color={tool === ToolType.DIMENSION ? "#3b82f6" : "#ec4899"} 
                        anchorX="center" 
                        anchorY="bottom"
                        depthTest={false}
                    >
                        {formatValue(dist)}
                    </Text>
                </group>
            );
        }

        // Phase 2: Start -> End ... Offset to Cursor (Waiting for 3rd point/placement)
        if (points.length === 2) {
             const p1 = new THREE.Vector3(points[0].x, points[0].y, points[0].z);
             const p2 = new THREE.Vector3(points[1].x, points[1].y, points[1].z);
             const p3 = currentPoint;

             // Project p3 onto line p1-p2 to find orthogonal offset
             const v12 = new THREE.Vector3().subVectors(p2, p1);
             const v13 = new THREE.Vector3().subVectors(p3, p1);
             // handle zero length case
             const lenSq = v12.lengthSq();
             const projectionFactor = lenSq > 0 ? v13.dot(v12) / lenSq : 0;
             const projectedPoint = p1.clone().add(v12.clone().multiplyScalar(projectionFactor));

             // The offset vector from the line to the cursor
             const offsetVector = new THREE.Vector3().subVectors(p3, projectedPoint);

             const dimStart = p1.clone().add(offsetVector);
             const dimEnd = p2.clone().add(offsetVector);
             const midPoint = new THREE.Vector3().addVectors(dimStart, dimEnd).multiplyScalar(0.5);

             // Add gap to extension lines logic for preview
             const GAP_SIZE = 0.05; 
             const offsetDir = offsetVector.clone().normalize();
             const offsetLen = offsetVector.length();
             const useGap = offsetLen > GAP_SIZE * 1.5;

             const ext1Start = useGap ? p1.clone().add(offsetDir.clone().multiplyScalar(GAP_SIZE)) : p1;
             const ext2Start = useGap ? p2.clone().add(offsetDir.clone().multiplyScalar(GAP_SIZE)) : p2;

             const color = tool === ToolType.DIMENSION ? "#3b82f6" : "#ec4899";

             const quaternion = getDimensionRotation(dimStart, dimEnd, offsetVector);

             return (
                <group>
                    <SimpleLine points={[dimStart, dimEnd]} color={color} opacity={0.8} />
                    <SimpleLine points={[ext1Start, dimStart]} color="#999" dashed opacity={0.5} />
                    <SimpleLine points={[ext2Start, dimEnd]} color="#999" dashed opacity={0.5} />
                    <mesh position={dimStart}><sphereGeometry args={[0.03]} /><meshBasicMaterial color={color} depthTest={false} /></mesh>
                    <mesh position={dimEnd}><sphereGeometry args={[0.03]} /><meshBasicMaterial color={color} depthTest={false} /></mesh>
                    <Text 
                        position={midPoint}
                        quaternion={quaternion} 
                        fontSize={0.25} 
                        color={color} 
                        anchorX="center" 
                        anchorY="bottom" 
                        outlineWidth={0.02} 
                        outlineColor="#ffffff" 
                        depthTest={false}
                        renderOrder={1000}
                    >
                        {formatValue(p1.distanceTo(p2))}
                    </Text>
                </group>
            );
        }
    }

    if (points.length === 0) return null;
    const startPoint = points[points.length-1];
    const startVec = new THREE.Vector3(startPoint.x, startPoint.y, startPoint.z);

    if (tool === ToolType.DRAW_LINE) { 
        return <SimpleLine points={[startVec, currentPoint]} color="black" dashed />; 
    }

    // --- RECT TOOL PREVIEW (Enhanced with dimensions) ---
    if (tool === ToolType.DRAW_RECT) {
        const start = points[0];
        const startV = new THREE.Vector3(start.x, start.y, start.z);
        const { right, top } = getLocalBasis(drawingNormal);
        const diff = new THREE.Vector3().subVectors(currentPoint, startV);
        const w = diff.dot(right); 
        const h = diff.dot(top);

        const p1 = startV;
        const p2 = startV.clone().add(right.clone().multiplyScalar(w));
        const p3 = startV.clone().add(right.clone().multiplyScalar(w)).add(top.clone().multiplyScalar(h));
        const p4 = startV.clone().add(top.clone().multiplyScalar(h));
        const rectPoints = [p1, p2, p3, p4, p1];

        // Midpoints for labels
        const widthMid = p1.clone().add(right.clone().multiplyScalar(w / 2));
        const heightMid = p2.clone().add(top.clone().multiplyScalar(h / 2));

        return (
            <group>
                <SimpleLine points={rectPoints} color="black" dashed />
                {/* Width Label */}
                <Billboard position={[widthMid.x, widthMid.y + 0.1, widthMid.z]}>
                    <Text fontSize={0.25} color="#000" depthTest={false}>
                        {formatValue(Math.abs(w))}
                    </Text>
                </Billboard>
                {/* Depth Label */}
                 <Billboard position={[heightMid.x, heightMid.y + 0.1, heightMid.z]}>
                    <Text fontSize={0.25} color="#000" depthTest={false}>
                        {formatValue(Math.abs(h))}
                    </Text>
                </Billboard>
            </group>
        );
    }

    if (tool === ToolType.DRAW_CIRCLE) {
        const start = points[0];
        const startV = new THREE.Vector3(start.x, start.y, start.z);
        const radius = startV.distanceTo(currentPoint);
        const circlePts = createCirclePoints(radius);
        // Transform circle points to world
        const worldPts = circlePts.map(p => new THREE.Vector3(p.x + startV.x, p.y + startV.y, p.z + startV.z)); // Simplified for flat circle
        return (
            <group>
                <SimpleLine points={worldPts} color="black" dashed />
                <SimpleLine points={[startV, currentPoint]} color="gray" dashed />
            </group>
        );
    }

    return null;
};

const InteractionLayer: React.FC<{
    shapes: IShape[];
    tool: ToolType;
    setCursorPos: (v: THREE.Vector3) => void;
    setSnapInfo: (s: SnapResult | null) => void;
    cursorPos: THREE.Vector3;
    snapInfo: SnapResult | null;
    drawPoints: IPoint[];
    isDragging: boolean;
    drawingHeight: number;
    typedInput: string;
    guideCreating: any;
    rotateState: RotateState;
    drawingNormal: THREE.Vector3;
    isGizmoDragging: boolean;
    inferenceGuide: InferenceGuide | null;
    setInferenceGuide: (g: InferenceGuide | null) => void;
    onPointerDown?: (e: ThreeEvent<PointerEvent>) => void;
    onPointerUp?: (e: ThreeEvent<PointerEvent>) => void;
    onClick?: (e: ThreeEvent<MouseEvent>) => void;
}> = ({ shapes, tool, setCursorPos, setSnapInfo, cursorPos, snapInfo, drawPoints, isDragging, drawingHeight, typedInput, guideCreating, rotateState, drawingNormal, isGizmoDragging, inferenceGuide, setInferenceGuide, onPointerDown, onPointerUp, onClick }) => {
    const { setMeasurement, formatValue, layers } = useApp();
    const updateMeasurement = useCallback((pos: THREE.Vector3, input?: string) => {
        let text = '';
        if ((tool === ToolType.MEASURE || tool === ToolType.GUIDE_LINE) && guideCreating.active && guideCreating.edge) {
             const p1 = guideCreating.edge[0]; const p2 = guideCreating.edge[1]; const edgeVec = new THREE.Vector3().subVectors(p2, p1); const pointVec = new THREE.Vector3().subVectors(pos, p1); const projected = p1.clone().add(edgeVec.clone().multiplyScalar(pointVec.dot(edgeVec) / edgeVec.lengthSq())); const dist = pos.distanceTo(projected); text = `偏移距離: ${formatValue(dist)}`;
        } else if (tool === ToolType.GUIDE_LINE && guideCreating.active && !guideCreating.edge) {
             text = '拖曳以建立軸向輔助線';
        } else if (tool === ToolType.ROTATE) {
             text = '拖曳旋轉環進行旋轉';
        } else if (tool === ToolType.DRAW_TEXT) {
             text = '點擊畫面以新增文字';
        } else if (tool === ToolType.DIMENSION || tool === ToolType.MEASURE) {
             if (drawPoints.length === 0) text = '點擊第一個點 (起點)';
             else if (drawPoints.length === 1) {
                 const start = new THREE.Vector3(drawPoints[0].x, drawPoints[0].y, drawPoints[0].z);
                 const dist = start.distanceTo(pos);
                 text = `點擊第二個點 (終點) [${formatValue(dist)}]`;
             } else if (drawPoints.length === 2) {
                 const p1 = new THREE.Vector3(drawPoints[0].x, drawPoints[0].y, drawPoints[0].z);
                 const p2 = new THREE.Vector3(drawPoints[1].x, drawPoints[1].y, drawPoints[1].z);
                 const dist = p1.distanceTo(p2);
                 text = `距離: ${formatValue(dist)} (拖曳調整位置，點擊放置)`;
             }
        } else if (drawPoints.length > 0) {
            const start = drawPoints[drawPoints.length - 1]; const current = pos; const dist = Math.sqrt((current.x - start.x)**2 + (current.y - start.y)**2 + (current.z - start.z)**2);
            if (tool === ToolType.DRAW_LINE) text = `長度: ${input ? input : formatValue(dist)}`;
            else if (tool === ToolType.DRAW_RECT) {
                const startVec = new THREE.Vector3(start.x, start.y, start.z);
                const { right, top } = getLocalBasis(drawingNormal);
                const diff = new THREE.Vector3().subVectors(pos, startVec);
                const w = Math.abs(diff.dot(right));
                const h = Math.abs(diff.dot(top));
                text = input ? `寬度, 深度: ${input}` : `寬度: ${formatValue(w)}, 深度: ${formatValue(h)}`;
            }
            else if (tool === ToolType.DRAW_CIRCLE) text = `半徑: ${input ? input : formatValue(dist)}`;
        } else {
             if ([ToolType.DRAW_LINE, ToolType.DRAW_RECT, ToolType.DRAW_CIRCLE, ToolType.MEASURE, ToolType.GUIDE_LINE].includes(tool)) text = `X ${formatValue(pos.x)}, Z ${formatValue(pos.z)}`;
        }
        if (input !== undefined) text += '|';
        setMeasurement(text);
    }, [drawPoints, tool, formatValue, setMeasurement, guideCreating, rotateState, drawingNormal]);

    useEffect(() => { 
        if (tool === ToolType.ROTATE || isGizmoDragging) return;
        if (typedInput) updateMeasurement(cursorPos, typedInput); else updateMeasurement(cursorPos); 
    }, [typedInput, cursorPos, updateMeasurement, rotateState.phase, rotateState.lockedAxis, tool, isGizmoDragging]); 

    const onPointerMove = useCallback((e: ThreeEvent<PointerEvent>) => {
        if (tool === ToolType.SELECT || tool === ToolType.PUSH_PULL || tool === ToolType.ROTATE || isGizmoDragging) return;

        const intersectPoint = (e as any).point; 
        if (isDragging && drawPoints.length > 0 && tool !== ToolType.DRAW_LINE && tool !== ToolType.DIMENSION) {
            const startPoint = new THREE.Vector3(drawPoints[0].x, drawPoints[0].y, drawPoints[0].z);
            const plane = new THREE.Plane().setFromNormalAndCoplanarPoint(drawingNormal, startPoint);
            const target = new THREE.Vector3();
            const hit = e.ray.intersectPlane(plane, target);
            if (hit) { setCursorPos(target); setSnapInfo(null); if (!typedInput) updateMeasurement(target); return; }
        }

        const shapeIntersections = (e.intersections as unknown as THREE.Intersection[]).filter(i => (i.object.userData?.isShape || i.object.parent?.userData?.isShape) && i.object !== (e as any).object);
        const visibleIntersections = shapeIntersections.filter(i => { const obj = i.object; const shapeId = obj.userData?.id || obj.parent?.userData?.id; const shape = shapes.find(s => s.id === shapeId); if (!shape) return false; const layer = layers.find(l => l.id === shape.layerId); return layer ? layer.visible : true; });
        const topShapeIntersect = visibleIntersections.length > 0 ? visibleIntersections[0] : undefined;
        const visibleShapes = shapes.filter(s => { const layer = layers.find(l => l.id === s.layerId); return layer ? layer.visible : true; });
        const snap = getGeometrySnap(intersectPoint, e.ray, visibleShapes, drawPoints, SNAP_THRESHOLD, topShapeIntersect);

        if ((tool === ToolType.DIMENSION || tool === ToolType.MEASURE) && drawPoints.length === 2) {
            if (snap.type !== 'grid' && snap.type !== 'face' && snap.type !== 'none') {
                setCursorPos(snap.position);
                setSnapInfo(snap);
            } else {
                let smoothPos = intersectPoint.clone();
                const startY = drawPoints[0].y;
                const endY = drawPoints[1].y;
                if (Math.abs(startY - endY) < 0.05) {
                    smoothPos.y = startY; 
                }
                setCursorPos(smoothPos);
                setSnapInfo(null);
            }
            if (!typedInput) updateMeasurement(snap.position); 
            return;
        }

        let newInferenceGuide: InferenceGuide | null = null;
        if (tool === ToolType.DRAW_LINE && drawPoints.length > 0) {
            const lastPt = drawPoints[drawPoints.length - 1];
            if (snap.type === 'grid' || snap.type === 'face' || snap.type === 'none') {
                 const dx = Math.abs(snap.position.x - lastPt.x);
                 const dz = Math.abs(snap.position.z - lastPt.z);
                 if (dx < ALIGN_THRESHOLD && dx < dz) {
                     snap.position.x = lastPt.x; 
                     snap.type = 'align';
                     newInferenceGuide = { 
                        type: 'z', 
                        start: new THREE.Vector3(lastPt.x, lastPt.y, lastPt.z), 
                        end: new THREE.Vector3(lastPt.x, snap.position.y, snap.position.z + (snap.position.z > lastPt.z ? 100 : -100)) 
                     };
                 } else if (dz < ALIGN_THRESHOLD) {
                     snap.position.z = lastPt.z; 
                     snap.type = 'align';
                     newInferenceGuide = { 
                        type: 'x', 
                        start: new THREE.Vector3(lastPt.x, lastPt.y, lastPt.z), 
                        end: new THREE.Vector3(snap.position.x + (snap.position.x > lastPt.x ? 100 : -100), snap.position.y, lastPt.z) 
                     };
                 }
            }
        }
        setInferenceGuide(newInferenceGuide);
        setCursorPos(snap.position); setSnapInfo(snap); if (!typedInput) updateMeasurement(snap.position);
    }, [tool, shapes, layers, drawPoints, setCursorPos, setSnapInfo, updateMeasurement, typedInput, isDragging, drawingNormal, isGizmoDragging, setInferenceGuide]);

    if (tool === ToolType.SELECT || tool === ToolType.PUSH_PULL) return null;
    return (
        <group>
            <mesh 
                rotation={[-Math.PI / 2, 0, 0]} 
                position={[0, 0.005, 0]} 
                onPointerMove={onPointerMove}
                onPointerDown={onPointerDown}
                onPointerUp={onPointerUp}
                onClick={onClick}
            >
                <planeGeometry args={[1000, 1000]} />
                <meshBasicMaterial visible={false} />
            </mesh>
             {snapInfo && tool !== ToolType.ROTATE && !isGizmoDragging && ( <><SnapIndicator position={snapInfo.position} type={snapInfo.type} snapEdge={snapInfo.snapEdge} /><CursorTooltip text={snapInfo.type === 'none' ? '' : snapInfo.type} position={snapInfo.position} type={snapInfo.type} /></> )}
             <InferenceGuideRenderer guide={inferenceGuide} />
             <DrawingPreview tool={tool} points={drawPoints} cursorPos={cursorPos} guideCreating={guideCreating} drawingNormal={drawingNormal} />
        </group>
    );
};

const useDrawingManager = () => {
    // ... (unchanged)
    const { tool, addShape, shapes, wallThickness, setTool, replaceShapes, updateShape, setMeasurement, activeLayerId, addGuideLine, removeShape } = useApp();
    const [drawPoints, setDrawPoints] = useState<IPoint[]>([]);
    const [cursorPos, setCursorPos] = useState<THREE.Vector3>(new THREE.Vector3());
    const [snapInfo, setSnapInfo] = useState<SnapResult | null>(null);
    const [isDragging, setIsDragging] = useState(false);
    const [drawingHeight, setDrawingHeight] = useState(0);
    const [typedInput, setTypedInput] = useState('');
    const [drawingNormal, setDrawingNormal] = useState<THREE.Vector3>(new THREE.Vector3(0, 1, 0));
    const [guideCreating, setGuideCreating] = useState<{ active: boolean, start: THREE.Vector3, current: THREE.Vector3, edge: [THREE.Vector3, THREE.Vector3] | null }>({ active: false, start: new THREE.Vector3(), current: new THREE.Vector3(), edge: null });
    const [inferenceGuide, setInferenceGuide] = useState<InferenceGuide | null>(null);
    const currentChainIds = useRef<string[]>([]); // To track continuous lines

    useEffect(() => { 
        setDrawPoints([]); setSnapInfo(null); setIsDragging(false); setDrawingHeight(0); setMeasurement(''); setTypedInput(''); setGuideCreating({ active: false, start: new THREE.Vector3(), current: new THREE.Vector3(), edge: null }); setDrawingNormal(new THREE.Vector3(0, 1, 0)); setInferenceGuide(null); currentChainIds.current = [];
    }, [tool, setMeasurement]);

    const attemptGeometryCut = useCallback((p1: THREE.Vector3, p2: THREE.Vector3) => {
        let cutOccurred = false;
        const start = { x: p1.x, y: 0, z: p1.z };
        const end = { x: p2.x, y: 0, z: p2.z };

        const flatShapes = shapes.filter(s => (s.type === 'flat' || s.type === 'solid') && s.name !== 'Edge');
        const idsToRemove = new Set<string>();
        const shapesToAddList: IShape[] = [];

        for (const shape of flatShapes) {
             if (idsToRemove.has(shape.id)) continue;
             if (Math.abs(shape.position[1] - p1.y) > 0.1) continue;

             const worldPoints = shape.points.map(p => {
                 const wp = transformPoint(p, shape);
                 return { x: wp.x, y: 0, z: wp.z };
             });

             const splitResult = cutPolygonBySegment(worldPoints, start, end);
             if (splitResult) {
                 const [polyA, polyB] = splitResult;

                 const createFragment = (points: IPoint[], suffix: string) => {
                     let minX = Infinity, maxX = -Infinity, minZ = Infinity, maxZ = -Infinity;
                     points.forEach(p => { if(p.x < minX) minX = p.x; if(p.x > maxX) maxX = p.x; if(p.z < minZ) minZ = p.z; if(p.z > maxZ) maxZ = p.z; });
                     const cx = (minX + maxX) / 2;
                     const cz = (minZ + maxZ) / 2;
                     const localPoints = points.map(p => ({ x: p.x - cx, y: 0, z: p.z - cz }));

                     return {
                         ...shape,
                         id: `split-${Date.now()}-${suffix}`,
                         points: localPoints,
                         position: [cx, shape.position[1], cz] as [number, number, number],
                         rotation: [0, 0, 0] as [number, number, number], 
                         scale: [1, 1, 1] as [number, number, number],
                         name: shape.name
                     };
                 };

                 shapesToAddList.push(createFragment(polyA, 'A'));
                 shapesToAddList.push(createFragment(polyB, 'B'));
                 idsToRemove.add(shape.id);
                 cutOccurred = true;
             }
        }
        if (cutOccurred) {
            replaceShapes(Array.from(idsToRemove), shapesToAddList);
        }
    }, [shapes, replaceShapes]);

    const addPoint = useCallback((point: THREE.Vector3) => {
        if (drawPoints.length > 0) {
            const start = drawPoints[0];
            const dist = point.distanceTo(new THREE.Vector3(start.x, start.y, start.z));

            if (dist < SNAP_THRESHOLD) {
                const finalPoints = [...drawPoints];
                const idsToRemove = [...currentChainIds.current];
                currentChainIds.current = [];

                const createShapeObj = (base: Partial<IShape>): IShape => ({ ...base as IShape, layerId: activeLayerId });
                let minX = Infinity, maxX = -Infinity, minZ = Infinity, maxZ = -Infinity;
                finalPoints.forEach(p => { if(p.x < minX) minX = p.x; if(p.x > maxX) maxX = p.x; if(p.z < minZ) minZ = p.z; if(p.z > maxZ) maxZ = p.z; });
                const cx = (minX + maxX) / 2; const cz = (minZ + maxZ) / 2;
                const localPoints = finalPoints.map(p => ({ x: p.x - cx, y: 0, z: p.z - cz }));

                const newFace = createShapeObj({
                    id: `face-${Date.now()}`,
                    type: 'flat',
                    name: '平面',
                    points: localPoints,
                    height: DEFAULT_HEIGHT,
                    color: FLAT_COLOR,
                    position: [cx, finalPoints[0].y, cz],
                    rotation: [0, 0, 0],
                    scale: [1, 1, 1]
                });

                replaceShapes(idsToRemove, [newFace]);
                setDrawPoints([]);
                setMeasurement('已建立平面');
                return;
            }
        }

        const newPoint = { x: point.x, y: point.y, z: point.z };
        const newPointsList = [...drawPoints, newPoint];
        setDrawPoints(newPointsList);

        if (tool === ToolType.DRAW_LINE && drawPoints.length > 0) {
            const prev = drawPoints[drawPoints.length - 1];
            const p1 = new THREE.Vector3(prev.x, prev.y, prev.z);
            const p2 = point;

            const lineId = `line-${Date.now()}-${Math.random()}`;
            const lineShape: IShape = {
                id: lineId,
                layerId: activeLayerId,
                type: 'line',
                name: '直線',
                points: [{ x: 0, y: 0, z: 0 }, { x: p2.x - p1.x, y: p2.y - p1.y, z: p2.z - p1.z }],
                height: 0,
                color: '#000000',
                position: [p1.x, p1.y, p1.z],
                rotation: [0, 0, 0],
                scale: [1, 1, 1]
            };
            addShape(lineShape);

            currentChainIds.current.push(lineShape.id);
            setDrawPoints([{ x: p2.x, y: p2.y, z: p2.z }]); 
            attemptGeometryCut(p1, p2);
            return;
        }

        // RECT
        if (tool === ToolType.DRAW_RECT && newPointsList.length === 2) {
             const start = newPointsList[0];
             const end = newPointsList[1];
             const startV = new THREE.Vector3(start.x, start.y, start.z);
             const endV = new THREE.Vector3(end.x, end.y, end.z);

             const { right, top } = getLocalBasis(drawingNormal);
             const diff = new THREE.Vector3().subVectors(endV, startV);
             const w = diff.dot(right);
             const h = diff.dot(top);

             const shape: IShape = {
                 id: `rect-${Date.now()}`,
                 layerId: activeLayerId,
                 type: 'flat',
                 name: '矩形',
                 points: [
                    { x: 0, y: 0, z: 0 },
                    { x: w, y: 0, z: 0 },
                    { x: w, y: 0, z: h },
                    { x: 0, y: 0, z: h },
                    { x: 0, y: 0, z: 0 }
                 ],
                 height: DEFAULT_HEIGHT,
                 color: FLAT_COLOR,
                 position: [start.x, start.y, start.z],
                 rotation: [0, 0, 0],
                 scale: [1, 1, 1]
             };

             // Simple normal adjustment (assuming flat or Y-up for now as base)
             const quat = new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, 1, 0), drawingNormal);
             const euler = new THREE.Euler().setFromQuaternion(quat);
             shape.rotation = [euler.x, euler.y, euler.z];

             addShape(shape);
             setDrawPoints([]);
        }

        // CIRCLE
        if (tool === ToolType.DRAW_CIRCLE && newPointsList.length === 2) {
            const center = newPointsList[0];
            const perimeter = newPointsList[1];
            const r = Math.sqrt((center.x - perimeter.x)**2 + (center.z - perimeter.z)**2);

            const circlePoints = createCirclePoints(r);
            const shape: IShape = {
                 id: `circle-${Date.now()}`,
                 layerId: activeLayerId,
                 type: 'flat',
                 name: '圓形',
                 points: circlePoints,
                 height: DEFAULT_HEIGHT,
                 color: FLAT_COLOR,
                 position: [center.x, center.y, center.z],
                 rotation: [0, 0, 0],
                 scale: [1, 1, 1]
            };
            addShape(shape);
            setDrawPoints([]);
        }

        // TEXT
        if (tool === ToolType.DRAW_TEXT && newPointsList.length === 1) {
             const p = newPointsList[0];
             const shape: IShape = {
                 id: `text-${Date.now()}`,
                 layerId: activeLayerId,
                 type: 'text',
                 name: '文字',
                 points: [{x:0, y:0, z:0}],
                 height: 0,
                 color: '#000000',
                 position: [p.x, p.y, p.z],
                 rotation: [-Math.PI/2, 0, 0],
                 scale: [1, 1, 1],
                 content: 'Text',
                 fontSize: 0.5
             };
             addShape(shape);
             setDrawPoints([]);
        }

        // DIMENSION / MEASURE
        if ((tool === ToolType.DIMENSION || tool === ToolType.MEASURE) && newPointsList.length === 3) {
            const p1 = newPointsList[0];
            const p2 = newPointsList[1];
            const p3 = newPointsList[2];

            if (tool === ToolType.DIMENSION) {
                const shape: IShape = {
                    id: `dim-${Date.now()}`,
                    layerId: activeLayerId,
                    type: 'dimension',
                    name: '尺寸',
                    points: [p1, p2, p3],
                    height: 0,
                    color: '#3b82f6',
                    position: [0, 0, 0],
                    rotation: [0, 0, 0],
                    scale: [1, 1, 1]
                };
                addShape(shape);
            }
            setDrawPoints([]);
        }
    }, [drawPoints, tool, activeLayerId, addShape, replaceShapes, attemptGeometryCut, drawingNormal, currentChainIds]);

    const handlePointerDown = useCallback((e: ThreeEvent<PointerEvent>) => {
        if (e.button !== 0) return;
        setIsDragging(true);
    }, []);

    const handlePointerUp = useCallback((e: ThreeEvent<PointerEvent>) => {
        setIsDragging(false);
    }, []);

    const handleClick = useCallback((e: ThreeEvent<MouseEvent>) => {
        if (tool === ToolType.SELECT || tool === ToolType.ROTATE || tool === ToolType.PUSH_PULL) return;
        if (snapInfo) {
            addPoint(snapInfo.position);
        } else {
            addPoint(e.point);
        }
    }, [tool, snapInfo, addPoint]);

    return {
        drawPoints,
        cursorPos,
        setCursorPos,
        snapInfo,
        setSnapInfo,
        isDragging,
        drawingHeight,
        typedInput,
        guideCreating,
        drawingNormal,
        inferenceGuide,
        setInferenceGuide,
        handlePointerDown,
        handlePointerUp,
        handleClick
    };
};

